begin;
DO $calendar$
begin
 perform 1 from public.marketing_calendar_plans where id='noviembre-2026' for update;
 if (select meta->>'cadence_revision' from public.marketing_calendar_plans where id='noviembre-2026')='alternating-daily-v4' then return; end if;
 if not exists(select 1 from public.marketing_calendar_plans where id='noviembre-2026' and meta='{"end": "2026-12-06", "scope": "5 reels (4 orgánicos + 1 adicional para pauta Meta) + 15 posts de feed + 15 stories individuales en total. Solo 2 rodajes: jueves 5/11 confirmado y jueves 19/11 propuesto. Cada story es una sola pieza, no una secuencia diaria. Horarios propuestos; el calendario no publica ni activa pauta.", "start": "2026-11-01", "title": "Calendario comercial · noviembre 2026", "edition": "2026-11-03", "sources": [{"url": "https://about.fb.com/news/2024/10/best-practices-education-hub-creators-instagram/", "title": "Meta · Best Practices de Instagram", "finding": "Meta organiza recomendaciones de creación, interacción y alcance y ofrece consejos personalizados en el panel profesional. Sustenta revisar Insights propios, sin afirmar una hora universal."}, {"url": "https://about.fb.com/news/2024/12/trial-reels-try-content-non-followers-first-see-what-perfoms-best/", "title": "Meta · Trial Reels", "finding": "Meta describe pruebas con no seguidores para explorar formatos. Si la función aparece en la cuenta, usarla en R01 o R03; mantener R02 y R04 en el calendario normal por su vigencia. El plan ahora incluye el quinto reel de pauta autorizado por Samuel; las tomas alternativas no añaden más reels."}, {"url": "https://about.fb.com/news/2025/06/inspiring-creativity-that-brings-people-together/", "title": "Meta · Creatividad y pruebas", "finding": "Apoya experimentar con contenido y observar la respuesta. Los formatos y guiones propuestos aquí son una inferencia creativa para Importados, no un estudio de ventas de esta cuenta."}, {"url": "https://www.instagram.com/tiendasimportados/", "title": "Instagram de Importados · revisión manual pendiente", "finding": "Fuente propia a contrastar por el equipo; no se pudo auditar el feed actual desde esta sesión."}], "strategy": [{"body": "R01: recorrido POV local. R02: invitación orgánica breve de tres motivos. R03: antes/después navideño. R04: lista navideña/Black Friday. R05: anuncio adicional de inauguración con todas las dinámicas, pensado para Meta Ads y publicado el 9/11 antes del evento. Son hipótesis creativas para la tienda, sin promesa de viralidad.", "title": "Cinco reels, funciones distintas"}, {"body": "Natillada y ubicación generan confianza; invitación y cobertura llevan a la inauguración; memoria del evento valida la experiencia; guías y lista preparan Black Friday; diciembre vuelve a inspiración sin prolongar el 20 %.", "title": "Una campaña que acumula intención"}, {"body": "Solo dos rodajes profesionales. Jueves 5/11 confirmado: R01, R02, R05 y banco fotográfico/recursos de inauguración y primera selección navideña. Jueves 19/11 propuesto: R03, R04 y banco de Navidad/Black Friday para el cierre. Horario sugerido 09:00–14:00 ambos días. El resto es edición, diseño y programación; no hay rodajes el 4, 9, 16 o 23. Para memorias de eventos, usar material existente/espontáneo compartido por tienda o agradecimientos gráficos; no fingir cobertura. Video propio vertical, voz, subtítulos y música apta para uso comercial. Las 15 stories se producen con ese mismo banco: una sola pieza por entrada del calendario. No se requieren 34 días de cobertura ni tres publicaciones diarias.", "title": "Grabación que se puede ejecutar"}, {"body": "Feed entre semana 18:30; sábado de lista/selección 11:30; anuncios de inicio 08:30/09:00. Solo 15 stories individuales en fechas seleccionadas: natillada, ubicación, inauguración, expectativa/venta de Black Friday y Navidad. No se incluyen secuencias diarias ni cobertura adicional como entregables. America/Bogota. Ajustar con Insights propios tras dos semanas: no tenemos métricas actuales de la cuenta. R03 pasa del 18 al 20/11 para editar después del segundo rodaje. R05 va el 9/11 a las 18:30. El 5/11 R01 tiene edición prioritaria para las 18:30; si no se aprueba a tiempo, reprogramar explícitamente.", "title": "Horario de partida, no «mejor hora» probada"}, {"body": "A las 24 h y 7 días: alcance, tiempo medio de reproducción y retención si están disponibles, compartidos/alcance, guardados/alcance, visitas al perfil y seguidores netos. Registrar consultas cualificadas por pieza (producto + sede + intención), visitas autodeclaradas y ventas verificadas por separado. No confundir reproducción, clic o consulta con venta.", "title": "Medición útil para retail"}, {"body": "R05 es la pieza adicional dedicada a convocatoria de inauguración: publicar el 9/11, con rodaje el 5, edición 6, revisión 7 y cierre de condiciones/aprobación 8. Propuesta de pauta 9–13/11, sin gasto ni activación desde el módulo. R02 queda orgánico para no duplicar inversión. R04 puede apoyar Black Friday si se autoriza otra campaña. Definir presupuesto, objetivo, destino y área de captación real de Niquía; comprobar bases y elegibilidad del anuncio antes de pautar premios. Medir consultas/visitas y ventas verificadas por separado, sin prometer resultados.", "title": "Pauta después de validar la pieza"}, {"body": "Las ocho fotos aportadas son referencias de licuadora, arrocera, trenes, Papá Noel, detalles dorados/plateados y árboles. Las etiquetas fotografiadas no son autorización para anunciar precios ni aplicarles otro descuento. Solicitar un inventario visual adicional de Navidad; mostrar luces, bolas, guirnaldas o empaques solo si se confirma que se venden.", "title": "Productos reales, no catálogo cerrado"}, {"body": "Se intentó revisar el perfil público y su embed el 3/11/2026: Instagram bloqueó la lectura automatizada y la búsqueda no recuperó publicaciones verificables. No se atribuyen métricas, frecuencia ni piezas recientes a la cuenta. El material previamente compartido muestra fachada, presentadora y estética amarilla/negra; se mantiene esa continuidad. Antes de producir, el equipo debe contrastar los 19 temas con el feed real y evitar duplicados.", "title": "Revisión de Instagram: alcance y límite"}, {"body": "Inauguración: 20 % en casi toda la tienda, sin transformarlo en «toda». Black Friday: 20 % en toda la tienda 27–29, pendiente de condiciones finales. Rifa: compra y seguir Instagram confirmados; faltan bases. Concurso: dos componentes de $500.000, sin sumar como efectivo. Artista: imitadora de Arelys Henao, sin aparentar contratación de la cantante original. Horarios de shows sin definir.", "title": "Promociones con información clara"}], "timezone": "America/Bogota", "stories_revision": "15-individual-stories-v3", "production_revision": "two-shoots-v2"}'::jsonb) then raise exception 'Calendar strategy changed; review cadence update'; end if;
 perform 1 from public.marketing_calendar_items where id='S1104' and plan_id='noviembre-2026' and revision=3 and data-'revision'='{"id": "S1104", "date": "2026-11-04", "kind": "story", "time": "18:30", "title": "Natillada: un recuerdo para compartir", "assets": [], "checks": ["Recibir foto real de la natillada y permiso de las personas reconocibles."], "format": "Foto vertical · 1 story", "script": [], "season": "niquia", "status": "planned", "caption": "Gracias por compartir nuestra natillada del 1 de noviembre 💛\n¿Estuviste aquí?", "outline": ["Foto real autorizada de la natillada del 1/11. Una sola story con texto «Gracias por compartir nuestra natillada 💛» y sticker «¿Estuviste aquí?»."], "end_date": "2026-11-04", "objective": "Una sola story para apoyar este hito, dentro del total de 15 stories individuales del plan.", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Entregable: exactamente 1 story individual (una imagen, un clip o un recompartido), no una secuencia de varias láminas. Usar banco de los rodajes 5/11 y 19/11 propuesto, o material existente autorizado. No añadir stories extra al paquete. Hora propuesta de Bogotá."}'::jsonb for update;
 if not found then raise exception 'Calendar item changed: S1104'; end if;
 perform 1 from public.marketing_calendar_items where id='P01' and plan_id='noviembre-2026' and revision=1 and data-'revision'='{"id": "P01", "date": "2026-11-04", "kind": "post", "time": "18:30", "title": "Así compartimos la natillada", "assets": [], "checks": ["Recibir 5–8 fotos reales de la natillada; no sustituirlas por imágenes de otro evento.", "Confirmar permiso de las personas reconocibles; no mostrar menores sin autorización de su responsable."], "format": "Carrusel · 1080 × 1350", "script": [], "season": "comunidad", "status": "planned", "caption": "Así se vivió nuestra natillada del 1 de noviembre 💛 Entre natilla, sonrisas y buenos momentos, seguimos conociendo a quienes hacen parte de Importados. Gracias por acompañarnos. ¿Estuviste por aquí? Cuéntanos cuál fue tu momento favorito. 🖤\n#TiendasImportados #Niquía #Bello", "outline": ["Portada: «Así compartimos el 1 de noviembre» + foto real de la natillada.", "Foto de preparación o servicio: «Los mejores momentos se comparten».", "Dos momentos espontáneos de asistentes y equipo, con permisos.", "Cierre: «Gracias por acompañarnos. Esto apenas comienza»."], "end_date": "2026-11-04", "objective": "Convertir la actividad del 1 de noviembre en cercanía y reconocimiento local.", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Seleccionar fotos el 3/11; evitar presentar la natillada como un evento futuro."}'::jsonb for update;
 if not found then raise exception 'Calendar item changed: P01'; end if;
 perform 1 from public.marketing_calendar_items where id='S1105' and plan_id='noviembre-2026' and revision=3 and data-'revision'='{"id": "S1105", "date": "2026-11-05", "kind": "story", "time": "18:45", "title": "Recorrido: descubre Importados Niquía", "assets": [], "checks": ["Publicar solo después de que R01 esté aprobado y publicado; reprogramar esta story si se retrasa."], "format": "Recompartido de R01 · 1 story", "script": [], "season": "niquia", "status": "planned", "caption": "Niquía, ya estamos abiertos 💛\nMira el recorrido y guarda nuestra ubicación.", "outline": ["Recompartir R01 ya aprobado en una sola story. Añadir «Niquía, ya estamos abiertos» y enlace a la ubicación. No añadir otra lámina."], "end_date": "2026-11-05", "objective": "Una sola story para apoyar este hito, dentro del total de 15 stories individuales del plan.", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Entregable: exactamente 1 story individual (una imagen, un clip o un recompartido), no una secuencia de varias láminas. Usar banco de los rodajes 5/11 y 19/11 propuesto, o material existente autorizado. No añadir stories extra al paquete. Hora propuesta de Bogotá."}'::jsonb for update;
 if not found then raise exception 'Calendar item changed: S1105'; end if;
 perform 1 from public.marketing_calendar_items where id='P02' and plan_id='noviembre-2026' and revision=1 and data-'revision'='{"id": "P02", "date": "2026-11-06", "kind": "post", "time": "18:30", "title": "Ya estamos en Niquía: guarda cómo llegar", "assets": [], "checks": ["Comprobar pin exacto y foto de entrada; no publicar ruta desde la estación sin recorrerla."], "format": "Carrusel · 1080 × 1350", "script": [], "season": "niquia", "status": "planned", "caption": "¡Niquía, ya puedes visitarnos! 💛 Estamos en Diagonal 55 Av 38-33, edificio Valkiria, Niquía, Bello.\nHorario de atención: 9:00 a. m. a 8:00 p. m.\nY el 14 y 15 de noviembre celebraremos nuestra gran inauguración. Guarda esta dirección y compártela con quien vendría contigo.\n#TiendasImportados #Niquía #Bello", "outline": ["Fachada actual: «Ya estamos abiertos en Niquía».", "Dirección completa con «edificio Valkiria» en alto contraste.", "Mapa sencillo con pin revisado; no inventar tiempo a pie desde el Metro.", "Horario 9–20 + fechas 14/15 + CTA guardar."], "end_date": "2026-11-06", "objective": "Resolver la fricción de ubicación antes de invitar al evento.", "responsible": "Polaris · contenido / Importados · validación", "production_notes": ""}'::jsonb for update;
 if not found then raise exception 'Calendar item changed: P02'; end if;
 perform 1 from public.marketing_calendar_items where id='S1106' and plan_id='noviembre-2026' and revision=3 and data-'revision'='{"id": "S1106", "date": "2026-11-06", "kind": "story", "time": "12:30", "title": "Guarda nuestra dirección en Niquía", "assets": [], "checks": ["Comprobar pin exacto de la entrada antes de enlazar Maps."], "format": "Imagen de ubicación · 1 story", "script": [], "season": "niquia", "status": "planned", "caption": "Ya puedes visitarnos 💛\nDiagonal 55 Av 38-33 · edificio Valkiria · Niquía\n9:00 a. m. – 8:00 p. m.", "outline": ["Foto de fachada del rodaje 1. Una sola pieza con dirección completa «Diagonal 55 Av 38-33 · edificio Valkiria · Niquía», horario 9 a. m.–8 p. m. y sticker de ubicación/Maps."], "end_date": "2026-11-06", "objective": "Una sola story para apoyar este hito, dentro del total de 15 stories individuales del plan.", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Entregable: exactamente 1 story individual (una imagen, un clip o un recompartido), no una secuencia de varias láminas. Usar banco de los rodajes 5/11 y 19/11 propuesto, o material existente autorizado. No añadir stories extra al paquete. Hora propuesta de Bogotá."}'::jsonb for update;
 if not found then raise exception 'Calendar item changed: S1106'; end if;
 perform 1 from public.marketing_calendar_items where id='P04' and plan_id='noviembre-2026' and revision=1 and data-'revision'='{"id": "P04", "date": "2026-11-10", "kind": "post", "time": "18:30", "title": "La fiesta de inauguración ya tiene fecha", "assets": [], "checks": ["Confirmar exclusiones del 20 %, condiciones, vigencia y sedes participantes. No anunciar «toda la tienda» en inauguración.", "Confirmar día y hora de cada artista y actividad; presentar a la artista como imitadora de Arelys Henao de Yo Me Llamo, sin sugerir que viene la cantante original.", "Autorizar fotografías, nombres artísticos y uso promocional de los artistas."], "format": "Carrusel · 1080 × 1350", "script": [], "season": "niquia", "status": "planned", "caption": "¡El 14 y 15 de noviembre celebramos en Niquía! 💛🖤 Tendremos música en vivo, la trova de Toto y Sirirí y una presentación de la imitadora de Arelys Henao de Yo Me Llamo.\nTambién habrá 20 % de descuento en gran parte de la tienda y actividades para compartir.\n📍 Diagonal 55 Av 38-33, edificio Valkiria, Niquía, Bello.\nMuy pronto te compartiremos horarios y condiciones. ¡Reserva las fechas!", "outline": ["Portada: «Gran inauguración · 14 y 15 de noviembre».", "Talento: Toto y Sirirí / imitadora de Arelys Henao de Yo Me Llamo, con fotos autorizadas.", "Descuento: «20 % en gran parte de la tienda» + exclusiones legibles.", "Dirección y CTA: «Ven acompañado». No atribuir cada artista a ambos días."], "end_date": "2026-11-10", "objective": "Dar razones concretas para asistir sin inventar programación.", "responsible": "Polaris · contenido / Importados · validación", "production_notes": ""}'::jsonb for update;
 if not found then raise exception 'Calendar item changed: P04'; end if;
 perform 1 from public.marketing_calendar_items where id='S1109' and plan_id='noviembre-2026' and revision=3 and data-'revision'='{"id": "S1109", "date": "2026-11-09", "kind": "story", "time": "18:45", "title": "Comparte el plan de inauguración", "assets": [], "checks": ["R05 publicado y aprobado; bases de rifa/concurso, condiciones del descuento y enlace accesible antes de compartir."], "format": "Recompartido de R05 · 1 story", "script": [], "season": "niquia", "status": "planned", "caption": "14 y 15 de noviembre: tenemos plan en Niquía 💛🖤\nMira todas las dinámicas y consulta las bases.", "outline": ["Recompartir R05 en una sola story, tras su aprobación. Añadir «14 y 15 de noviembre · ¿con quién vienes?» y enlace a programación/bases aprobadas. No presentarlo como anuncio pagado activo."], "end_date": "2026-11-09", "objective": "Una sola story para apoyar este hito, dentro del total de 15 stories individuales del plan.", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Entregable: exactamente 1 story individual (una imagen, un clip o un recompartido), no una secuencia de varias láminas. Usar banco de los rodajes 5/11 y 19/11 propuesto, o material existente autorizado. No añadir stories extra al paquete. Hora propuesta de Bogotá."}'::jsonb for update;
 if not found then raise exception 'Calendar item changed: S1109'; end if;
 perform 1 from public.marketing_calendar_items where id='P05' and plan_id='noviembre-2026' and revision=1 and data-'revision'='{"id": "P05", "date": "2026-11-12", "kind": "post", "time": "18:30", "title": "Premios y concurso: guía para participar", "assets": [], "checks": ["Aprobar bases de la rifa: compra mínima si aplica, fechas, comprobante, número de participaciones, requisitos, fecha/método del sorteo, entrega, modelos/cantidades de premios y revisión de requisitos aplicables. Compra + seguir Instagram es la única mecánica confirmada.", "Aprobar bases, edades, dinámica y seguridad del concurso «Culi chupado», cupos y entrega de premios: $500.000 en efectivo + $500.000 para gastar en tienda. No prometer $1.000.000 en efectivo.", "Sustituir la última frase editorial del caption por el enlace a bases definitivas; no publicar el borrador como anuncio."], "format": "Carrusel · 1080 × 1350", "script": [], "season": "niquia", "status": "planned", "caption": "La inauguración de Niquía también viene con premios 💛 Habrá una rifa de una moto y patinetes eléctricos. Para participar debes comprar en tienda y seguir a @tiendasimportados; consulta las bases completas antes de participar.\nAdemás, el concurso «Culi chupado» tendrá un premio de $500.000 en efectivo y $500.000 para gastar en la tienda.\nNos vemos el 14 y 15 de noviembre en Diagonal 55 Av 38-33, edificio Valkiria, Niquía, Bello.\nLa mecánica completa, los horarios y las condiciones deben acompañar esta publicación.", "outline": ["Portada: «Inauguración con premios · 14 y 15».", "Foto del premio real: moto AKT; confirmar denominación «Special 110X» antes de usarla.", "Patinetes eléctricos: confirmar cantidad y modelos reales.", "Rifa: compra en tienda + sigue Instagram + bases completas visibles.", "Concurso «Culi chupado»: $500.000 efectivo + $500.000 consumo; añadir requisitos aprobados.", "Última lámina: fechas/horarios del sorteo y enlace o QR a bases aprobadas."], "end_date": "2026-11-12", "objective": "Aclarar incentivos con reglas completas antes del fin de semana.", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Si no hay bases aprobadas el 11/11, reemplazar por carrusel de ubicación y ambiente. No promover la rifa incompleta."}'::jsonb for update;
 if not found then raise exception 'Calendar item changed: P05'; end if;
 perform 1 from public.marketing_calendar_items where id='S1112' and plan_id='noviembre-2026' and revision=3 and data-'revision'='{"id": "S1112", "date": "2026-11-12", "kind": "story", "time": "18:30", "title": "Rifa de inauguración: cómo participar", "assets": [], "checks": ["Aprobar bases completas, modelos/cantidades de premios, requisitos, sorteo y entrega; foto real o arte autorizado. No publicar sin bases accesibles."], "format": "Imagen de promoción · 1 story", "script": [], "season": "niquia", "status": "planned", "caption": "Rifa de inauguración 💛\nCompra en tienda + sigue @tiendasimportados\nConsulta requisitos y bases completas antes de participar.", "outline": ["Una sola pieza con foto real autorizada de premios. Texto «Rifa de moto AKT y patinetes eléctricos / Compra en tienda + sigue @tiendasimportados». Sticker a bases completas aprobadas y fechas 14/15. No resumir como único requisito si las bases incluyen más condiciones."], "end_date": "2026-11-12", "objective": "Una sola story para apoyar este hito, dentro del total de 15 stories individuales del plan.", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Entregable: exactamente 1 story individual (una imagen, un clip o un recompartido), no una secuencia de varias láminas. Usar banco de los rodajes 5/11 y 19/11 propuesto, o material existente autorizado. No añadir stories extra al paquete. Hora propuesta de Bogotá."}'::jsonb for update;
 if not found then raise exception 'Calendar item changed: S1112'; end if;
 perform 1 from public.marketing_calendar_items where id='P06' and plan_id='noviembre-2026' and revision=2 and data-'revision'='{"id": "P06", "date": "2026-11-14", "kind": "post", "time": "08:30", "title": "Hoy comienza nuestra gran inauguración", "assets": [], "checks": ["Confirmar exclusiones del 20 %, condiciones, vigencia y sedes participantes. No anunciar «toda la tienda» en inauguración."], "format": "Carrusel · 1080 × 1350", "script": [], "season": "niquia", "status": "planned", "caption": "¡Hoy empieza la celebración en Importados Niquía! 💛🖤 Este 14 y 15 de noviembre te esperamos en Diagonal 55 Av 38-33, edificio Valkiria, Niquía, Bello.\nVen a conocer la tienda, disfrutar el ambiente y descubrir el 20 % de descuento en gran parte de la tienda. Consulta las condiciones de la promoción en sede.\nHorario de tienda: 9:00 a. m. a 8:00 p. m. La programación de actividades se anunciará en nuestras stories. ¡Te esperamos!", "outline": ["Portada: «¡Es hoy! · Inauguración Niquía».", "Foto actual de tienda/equipo: abrir invitación.", "Descuento con exclusiones y vigencia aprobadas.", "Dirección, horario de tienda y programación aprobada si está lista."], "end_date": "2026-11-14", "objective": "Activar la visita durante el primer día.", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Pieza producida con banco del rodaje 1; horario de tienda distinto de shows. Si el personal comparte fotos espontáneas del 14, guardarlas para P07/P08. No se programa un tercer rodaje ni se necesita material futuro para este anuncio."}'::jsonb for update;
 if not found then raise exception 'Calendar item changed: P06'; end if;
