 update public.marketing_calendar_items set data='{"id": "P01", "date": "2026-11-05", "time": "11:30", "end_date": "2026-11-05", "kind": "post", "season": "comunidad", "title": "Así compartimos la natillada", "objective": "Convertir la actividad del 1 de noviembre en cercanía y reconocimiento local.", "caption": "Así se vivió nuestra natillada del 1 de noviembre 💛 Entre natilla, sonrisas y buenos momentos, seguimos conociendo a quienes hacen parte de Importados. Gracias por acompañarnos. ¿Estuviste por aquí? Cuéntanos cuál fue tu momento favorito. 🖤\n#TiendasImportados #Niquía #Bello", "outline": ["Portada: «Así compartimos el 1 de noviembre» + foto real de la natillada.", "Foto de preparación o servicio: «Los mejores momentos se comparten».", "Dos momentos espontáneos de asistentes y equipo, con permisos.", "Cierre: «Gracias por acompañarnos. Esto apenas comienza»."], "assets": [], "checks": ["Recibir 5–8 fotos reales de la natillada; no sustituirlas por imágenes de otro evento.", "Confirmar permiso de las personas reconocibles; no mostrar menores sin autorización de su responsable."], "script": [], "format": "Carrusel · 1080 × 1350", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Seleccionar fotos el 3/11; evitar presentar la natillada como un evento futuro. Alternancia diaria: este es un día de post; las stories van al día siguiente. En los cinco días con reel adicional, post a las 11:30 y reel a las 18:30.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='P01' and plan_id='noviembre-2026';
