 update public.marketing_calendar_items set data='{"id": "P02", "date": "2026-11-07", "time": "18:30", "end_date": "2026-11-07", "kind": "post", "season": "niquia", "title": "Ya estamos en Niquía: guarda cómo llegar", "objective": "Resolver la fricción de ubicación antes de invitar al evento.", "caption": "¡Niquía, ya puedes visitarnos! 💛 Estamos en Diagonal 55 Av 38-33, edificio Valkiria, Niquía, Bello.\nHorario de atención: 9:00 a. m. a 8:00 p. m.\nY el 14 y 15 de noviembre celebraremos nuestra gran inauguración. Guarda esta dirección y compártela con quien vendría contigo.\n#TiendasImportados #Niquía #Bello", "outline": ["Fachada actual: «Ya estamos abiertos en Niquía».", "Dirección completa con «edificio Valkiria» en alto contraste.", "Mapa sencillo con pin revisado; no inventar tiempo a pie desde el Metro.", "Horario 9–20 + fechas 14/15 + CTA guardar."], "assets": [], "checks": ["Comprobar pin exacto y foto de entrada; no publicar ruta desde la estación sin recorrerla."], "script": [], "format": "Carrusel · 1080 × 1350", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": " Alternancia diaria: este es un día de post; las stories van al día siguiente. En los cinco días con reel adicional, post a las 11:30 y reel a las 18:30.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='P02' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "S1106", "date": "2026-11-08", "time": "12:30", "end_date": "2026-11-08", "kind": "story", "season": "niquia", "title": "Guarda nuestra dirección en Niquía", "objective": "Una sola story para apoyar este hito, dentro del total de 15 stories individuales del plan.", "caption": "Ya puedes visitarnos 💛\nDiagonal 55 Av 38-33 · edificio Valkiria · Niquía\n9:00 a. m. – 8:00 p. m.", "outline": ["Foto de fachada del rodaje 1. Una sola pieza con dirección completa «Diagonal 55 Av 38-33 · edificio Valkiria · Niquía», horario 9 a. m.–8 p. m. y sticker de ubicación/Maps."], "assets": [], "checks": ["Comprobar pin exacto de la entrada antes de enlazar Maps."], "script": [], "format": "Imagen de ubicación · 1 story", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Entregable: exactamente 1 story individual (una imagen, un clip o un recompartido), no una secuencia de varias láminas. Usar banco de los rodajes 5/11 y 19/11 propuesto, o material existente autorizado. No añadir stories extra al paquete. Hora propuesta de Bogotá. Alternancia diaria: una sola story este día; el post corresponde al día anterior o siguiente. Los recompartidos se hacen después de publicar/aprobar el reel original.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='S1106' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "P04", "date": "2026-11-09", "time": "11:30", "end_date": "2026-11-09", "kind": "post", "season": "niquia", "title": "La fiesta de inauguración ya tiene fecha", "objective": "Dar razones concretas para asistir sin inventar programación.", "caption": "¡El 14 y 15 de noviembre celebramos en Niquía! 💛🖤 Tendremos música en vivo, la trova de Toto y Sirirí y una presentación de la imitadora de Arelys Henao de Yo Me Llamo.\nTambién habrá 20 % de descuento en gran parte de la tienda y actividades para compartir.\n📍 Diagonal 55 Av 38-33, edificio Valkiria, Niquía, Bello.\nMuy pronto te compartiremos horarios y condiciones. ¡Reserva las fechas!", "outline": ["Portada: «Gran inauguración · 14 y 15 de noviembre».", "Talento: Toto y Sirirí / imitadora de Arelys Henao de Yo Me Llamo, con fotos autorizadas.", "Descuento: «20 % en gran parte de la tienda» + exclusiones legibles.", "Dirección y CTA: «Ven acompañado». No atribuir cada artista a ambos días."], "assets": [], "checks": ["Confirmar exclusiones del 20 %, condiciones, vigencia y sedes participantes. No anunciar «toda la tienda» en inauguración.", "Confirmar día y hora de cada artista y actividad; presentar a la artista como imitadora de Arelys Henao de Yo Me Llamo, sin sugerir que viene la cantante original.", "Autorizar fotografías, nombres artísticos y uso promocional de los artistas."], "script": [], "format": "Carrusel · 1080 × 1350", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": " Alternancia diaria: este es un día de post; las stories van al día siguiente. En los cinco días con reel adicional, post a las 11:30 y reel a las 18:30.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='P04' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "S1109", "date": "2026-11-10", "time": "18:45", "end_date": "2026-11-10", "kind": "story", "season": "niquia", "title": "Comparte el plan de inauguración", "objective": "Una sola story para apoyar este hito, dentro del total de 15 stories individuales del plan.", "caption": "14 y 15 de noviembre: tenemos plan en Niquía 💛🖤\nMira todas las dinámicas y consulta las bases.", "outline": ["Recompartir R05 en una sola story, al día siguiente de su publicación, tras su aprobación. Añadir «14 y 15 de noviembre · ¿con quién vienes?» y enlace a programación/bases aprobadas. No presentarlo como anuncio pagado activo."], "assets": [], "checks": ["R05 publicado y aprobado; bases de rifa/concurso, condiciones del descuento y enlace accesible antes de compartir."], "script": [], "format": "Recompartido de R05 · 1 story", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Entregable: exactamente 1 story individual (una imagen, un clip o un recompartido), no una secuencia de varias láminas. Usar banco de los rodajes 5/11 y 19/11 propuesto, o material existente autorizado. No añadir stories extra al paquete. Hora propuesta de Bogotá. Alternancia diaria: una sola story este día; el post corresponde al día anterior o siguiente. Los recompartidos se hacen después de publicar/aprobar el reel original.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='S1109' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "P05", "date": "2026-11-11", "time": "11:30", "end_date": "2026-11-11", "kind": "post", "season": "niquia", "title": "Premios y concurso: guía para participar", "objective": "Aclarar incentivos con reglas completas antes del fin de semana.", "caption": "La inauguración de Niquía también viene con premios 💛 Habrá una rifa de una moto y patinetes eléctricos. Para participar debes comprar en tienda y seguir a @tiendasimportados; consulta las bases completas antes de participar.\nAdemás, el concurso «Culi chupado» tendrá un premio de $500.000 en efectivo y $500.000 para gastar en la tienda.\nNos vemos el 14 y 15 de noviembre en Diagonal 55 Av 38-33, edificio Valkiria, Niquía, Bello.\nLa mecánica completa, los horarios y las condiciones deben acompañar esta publicación.", "outline": ["Portada: «Inauguración con premios · 14 y 15».", "Foto del premio real: moto AKT; confirmar denominación «Special 110X» antes de usarla.", "Patinetes eléctricos: confirmar cantidad y modelos reales.", "Rifa: compra en tienda + sigue Instagram + bases completas visibles.", "Concurso «Culi chupado»: $500.000 efectivo + $500.000 consumo; añadir requisitos aprobados.", "Última lámina: fechas/horarios del sorteo y enlace o QR a bases aprobadas."], "assets": [], "checks": ["Aprobar bases de la rifa: compra mínima si aplica, fechas, comprobante, número de participaciones, requisitos, fecha/método del sorteo, entrega, modelos/cantidades de premios y revisión de requisitos aplicables. Compra + seguir Instagram es la única mecánica confirmada.", "Aprobar bases, edades, dinámica y seguridad del concurso «Culi chupado», cupos y entrega de premios: $500.000 en efectivo + $500.000 para gastar en tienda. No prometer $1.000.000 en efectivo.", "Sustituir la última frase editorial del caption por el enlace a bases definitivas; no publicar el borrador como anuncio."], "script": [], "format": "Carrusel · 1080 × 1350", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Si no hay bases aprobadas el 10/11, reemplazar por carrusel de ubicación y ambiente. No promover la rifa incompleta. Alternancia diaria: este es un día de post; las stories van al día siguiente. En los cinco días con reel adicional, post a las 11:30 y reel a las 18:30.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='P05' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "S1112", "date": "2026-11-12", "time": "18:30", "end_date": "2026-11-12", "kind": "story", "season": "niquia", "title": "Rifa de inauguración: cómo participar", "objective": "Una sola story para apoyar este hito, dentro del total de 15 stories individuales del plan.", "caption": "Rifa de inauguración 💛\nCompra en tienda + sigue @tiendasimportados\nConsulta requisitos y bases completas antes de participar.", "outline": ["Una sola pieza con foto real autorizada de premios. Texto «Rifa de moto AKT y patinetes eléctricos / Compra en tienda + sigue @tiendasimportados». Sticker a bases completas aprobadas y fechas 14/15. No resumir como único requisito si las bases incluyen más condiciones."], "assets": [], "checks": ["Aprobar bases completas, modelos/cantidades de premios, requisitos, sorteo y entrega; foto real o arte autorizado. No publicar sin bases accesibles."], "script": [], "format": "Imagen de promoción · 1 story", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Entregable: exactamente 1 story individual (una imagen, un clip o un recompartido), no una secuencia de varias láminas. Usar banco de los rodajes 5/11 y 19/11 propuesto, o material existente autorizado. No añadir stories extra al paquete. Hora propuesta de Bogotá. Alternancia diaria: una sola story este día; el post corresponde al día anterior o siguiente. Los recompartidos se hacen después de publicar/aprobar el reel original.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='S1112' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "P06", "date": "2026-11-13", "time": "08:30", "end_date": "2026-11-13", "kind": "post", "season": "niquia", "title": "Mañana empieza la gran inauguración", "objective": "Activar la visita el día anterior al primer día de inauguración.", "caption": "¡Mañana empieza la celebración en Importados Niquía! 💛🖤 Este 14 y 15 de noviembre te esperamos en Diagonal 55 Av 38-33, edificio Valkiria, Niquía, Bello.\nVen a conocer la tienda, disfrutar el ambiente y descubrir el 20 % de descuento en gran parte de la tienda. Consulta las condiciones de la promoción en sede.\nHorario de tienda: 9:00 a. m. a 8:00 p. m. La programación de actividades se anunciará en nuestras stories. ¡Te esperamos!", "outline": ["Portada: «¡Es mañana! · Inauguración Niquía».", "Foto actual de tienda/equipo: abrir invitación.", "Descuento con exclusiones y vigencia aprobadas.", "Dirección, horario de tienda y programación aprobada si está lista."], "assets": [], "checks": ["Confirmar exclusiones del 20 %, condiciones, vigencia y sedes participantes. No anunciar «toda la tienda» en inauguración."], "script": [], "format": "Carrusel · 1080 × 1350", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Pieza producida con banco del rodaje 1; horario de tienda distinto de shows. Si el personal comparte fotos espontáneas del 14, guardarlas para P07/P08. No se programa un tercer rodaje ni se necesita material futuro para este anuncio. Alternancia diaria: este es un día de post; las stories van al día siguiente. En los cinco días con reel adicional, post a las 11:30 y reel a las 18:30.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='P06' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "S1113", "date": "2026-11-14", "time": "08:45", "end_date": "2026-11-14", "kind": "story", "season": "niquia", "title": "¡Es hoy! Inauguración Niquía", "objective": "Una sola story para apoyar este hito, dentro del total de 15 stories individuales del plan.", "caption": "¡Es hoy, Niquía! 💛🖤\nGran inauguración · 14 y 15 de noviembre\nEdificio Valkiria · Diagonal 55 Av 38-33", "outline": ["Una sola imagen de fachada del banco del 5/11. Texto «¡Es hoy! / Gran inauguración · 14 y 15 NOV / Niquía · edificio Valkiria» y enlace a ubicación o programación confirmada. Sin simular cobertura en vivo."], "assets": [], "checks": ["Enlazar programación solo si está confirmada; de lo contrario enlazar ubicación."], "script": [], "format": "Imagen vertical · 1 story", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Entregable: exactamente 1 story individual (una imagen, un clip o un recompartido), no una secuencia de varias láminas. Usar banco de los rodajes 5/11 y 19/11 propuesto, o material existente autorizado. No añadir stories extra al paquete. Hora propuesta de Bogotá. Alternancia diaria: una sola story este día; el post corresponde al día anterior o siguiente. Los recompartidos se hacen después de publicar/aprobar el reel original.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='S1113' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "P07", "date": "2026-11-15", "time": "09:00", "end_date": "2026-11-15", "kind": "post", "season": "niquia", "title": "Segundo día: nos vemos en Niquía", "objective": "Mantener asistencia con prueba real del primer día.", "caption": "¡La celebración sigue hoy en Niquía! 💛 Gracias a quienes nos acompañaron ayer. Este 15 de noviembre seguimos de inauguración en Diagonal 55 Av 38-33, edificio Valkiria, Niquía, Bello.\nAcércate, conoce la variedad y aprovecha el 20 % de descuento en gran parte de la tienda, según condiciones de la promoción.\nMira nuestras stories para consultar la programación confirmada de hoy. 🖤", "outline": ["Portada: «Hoy seguimos de inauguración».", "Foto real del 14/11 con público autorizado.", "Programa del día 15 solo con horarios confirmados; si falta, usar foto de productos.", "Dirección y condiciones del descuento."], "assets": [], "checks": ["Confirmar exclusiones del 20 %, condiciones, vigencia y sedes participantes. No anunciar «toda la tienda» en inauguración.", "Confirmar permiso de las personas reconocibles; no mostrar menores sin autorización de su responsable.", "Si no hay fotografías del 14/11, usar variante con fotos del rodaje 1 identificadas como tienda; no aparentar cobertura."], "script": [], "format": "Carrusel · 1080 × 1350", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Usar fotos espontáneas del día 14 si las comparte la tienda. Si no hay material autorizado, sustituir las láminas de recuerdo por fotos del banco del 5/11 y texto de invitación; no presentarlas como cobertura del evento. Alternancia diaria: este es un día de post; las stories van al día siguiente. En los cinco días con reel adicional, post a las 11:30 y reel a las 18:30.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='P07' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "S1114", "date": "2026-11-16", "time": "18:30", "end_date": "2026-11-16", "kind": "story", "season": "comunidad", "title": "Gracias por celebrar en Niquía", "objective": "Una sola story para apoyar este hito, dentro del total de 15 stories individuales del plan.", "caption": "¡Gracias por celebrar con nosotros, Niquía! 💛🖤\nSeguimos aquí para acompañarte.", "outline": ["Una sola foto autorizada compartida por tienda, o agradecimiento gráfico con fachada del banco. Texto «Gracias por celebrar con nosotros, Niquía»; no presentar foto del banco como cobertura."], "assets": [], "checks": ["Validar material y permisos; no anunciar resultados ni ganadores no confirmados."], "script": [], "format": "Imagen vertical · 1 story", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Entregable: exactamente 1 story individual (una imagen, un clip o un recompartido), no una secuencia de varias láminas. Usar banco de los rodajes 5/11 y 19/11 propuesto, o material existente autorizado. No añadir stories extra al paquete. Hora propuesta de Bogotá. Alternancia diaria: una sola story este día; el post corresponde al día anterior o siguiente. Los recompartidos se hacen después de publicar/aprobar el reel original.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='S1114' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "P08", "date": "2026-11-17", "time": "18:30", "end_date": "2026-11-17", "kind": "post", "season": "comunidad", "title": "Gracias por una inauguración para recordar", "objective": "Conservar confianza y convertir asistentes en comunidad.", "caption": "¡Gracias por celebrar con nosotros, Niquía! 💛🖤 Nos quedamos con las sonrisas, la música y cada persona que pasó a conocernos este 14 y 15 de noviembre.\nDesliza para revivir algunos momentos. Si estuviste, cuéntanos qué fue lo que más disfrutaste. Seguimos aquí para acompañarte con variedad y nuevas ideas para tu hogar.\n#TiendasImportados #Niquía #Bello", "outline": ["Portada: foto propia de mayor emoción + «Gracias, Niquía».", "Ambiente y equipo.", "Trovadores y presentación artística realmente realizada.", "Actividad del concurso solo si fue realizada y se autorizan imágenes.", "Cierre: foto de fachada + «Nos seguimos encontrando aquí»."], "assets": [], "checks": ["Confirmar permiso de las personas reconocibles; no mostrar menores sin autorización de su responsable.", "Verificar qué actividades sí ocurrieron; no anunciar ganadores sin resultado y autorización confirmados."], "script": [], "format": "Carrusel · 1080 × 1350", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Usar material espontáneo autorizado que comparta la tienda. Si no lo hay, producir agradecimiento gráfico con fotos de fachada/equipo del rodaje 1 y adaptar caption/láminas sin aparentar recap del evento. No se añade jornada profesional para cobertura ni se inventan resultados/ganadores. Alternancia diaria: este es un día de post; las stories van al día siguiente. En los cinco días con reel adicional, post a las 11:30 y reel a las 18:30.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='P08' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "S1115", "date": "2026-11-18", "time": "18:30", "end_date": "2026-11-18", "kind": "story", "season": "navidad", "title": "Empezamos a preparar Navidad", "objective": "Una sola story para apoyar este hito, dentro del total de 15 stories individuales del plan.", "caption": "Tu rincón de Navidad empieza con una idea 🎄\n¿Qué te gustaría encontrar para tu casa?", "outline": ["Una sola composición de árbol y Papá Noel con banco del rodaje 1 o fotos existentes. Texto «¿Ya tienes tu rincón de Navidad?» y caja de preguntas."], "assets": [], "checks": ["Comprobar referencias disponibles antes de responder consultas."], "script": [], "format": "Imagen vertical · 1 story", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Entregable: exactamente 1 story individual (una imagen, un clip o un recompartido), no una secuencia de varias láminas. Usar banco de los rodajes 5/11 y 19/11 propuesto, o material existente autorizado. No añadir stories extra al paquete. Hora propuesta de Bogotá. Alternancia diaria: una sola story este día; el post corresponde al día anterior o siguiente. Los recompartidos se hacen después de publicar/aprobar el reel original.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='S1115' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "A02", "date": "2026-11-19", "time": "09:00", "end_date": "2026-11-19", "kind": "activity", "season": "niquia", "title": "Rodaje 2 · Navidad + Black Friday", "objective": "Grabar R03 y R04 y completar el banco fotográfico para los 15 posts y las stories de cierre de mes.", "caption": "", "outline": ["Fecha propuesta: jueves 19 de noviembre, 09:00–14:00; por confirmar con Samuel y la tienda. Es la segunda y última jornada de producción.", "09:00–09:30 · Revisar existencias/referencias, condiciones de Black Friday, espacios y permisos. No fijar precios sin validación.", "09:30–10:45 · R03: antes/después del rincón navideño, con encuadre fijo y detalles. Sacar fotos de cada paso para P09.", "10:45–12:00 · R04: lista navideña y Black Friday; filmar árbol, figura, tren, decoración y hogar con planos modulares.", "12:00–13:00 · Fotografías para P10–P15: dorado/plateado, selección de regalos y hogar; banco de stories hasta el 6/12.", "13:00–14:00 · Recursos de producto, interacción, fachadas y locuciones alternativas. Capturar versión sin descuento para diciembre.", "Entrega: P09 queda listo para el 21 a las 11:30; R03 el 21 a las 18:30; R04 edición 20–23, revisión y cierre 24 para publicar el 25."], "assets": [], "checks": ["Confirmar exclusiones del 20 %, condiciones, vigencia y sedes participantes. No anunciar «toda la tienda» en inauguración.", "Confirmar día y hora de cada artista y actividad; presentar a la artista como imitadora de Arelys Henao de Yo Me Llamo, sin sugerir que viene la cantante original."], "script": [], "format": "Rodaje 2 de 2 · jueves 19 propuesto", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Segunda fecha propuesta, aún no confirmada. Toda la captura profesional se concentra en las dos jornadas. La cobertura espontánea de tienda durante actividades no es un tercer rodaje contratado. No requiere regresar a filmar el 23 ni el 16 de noviembre.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='A02' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "P03", "date": "2026-11-19", "time": "18:30", "end_date": "2026-11-19", "kind": "post", "season": "navidad", "title": "¿Tu Navidad es dorada o plateada?", "objective": "Conseguir guardados y preferencias para preparar la selección de Black Friday.", "caption": "¿Team dorado o team plateado? ✨ Los detalles cambian el ambiente de tu casa. Desliza, elige tu estilo y guarda tus favoritos para empezar a preparar Navidad.\nCuéntanos tu elección y te ayudamos a consultar las referencias disponibles. 💛🖤\n#NavidadEnCasa #TiendasImportados #DecoraciónNavideña", "outline": ["Portada con contraste de piezas doradas y plateadas.", "Foto dorada en un ambiente real, no solo estantería.", "Foto plateada en el mismo encuadre.", "Composición con figura navideña y árbol; referencias por confirmar.", "Cierre: «Guarda tu estilo. ¿Dorado o plateado?»"], "assets": ["/marketing-assets/05-decoracion-dorada.jpeg", "/marketing-assets/06-decoracion-plateada.jpeg", "/marketing-assets/04-papa-noel.jpeg", "/marketing-assets/08-arboles.jpeg"], "checks": ["Confirmar existencias, referencias, sede y precios vigentes el día de publicación."], "script": [], "format": "Carrusel · 1080 × 1350", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Banco del rodaje 1 del 5/11 y fotografías ya recibidas. Producir composiciones reales doradas/plateadas; no atribuir material ni función no confirmados. Alternancia diaria: este es un día de post; las stories van al día siguiente. En los cinco días con reel adicional, post a las 11:30 y reel a las 18:30.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='P03' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "S1117", "date": "2026-11-20", "time": "18:30", "end_date": "2026-11-20", "kind": "story", "season": "navidad", "title": "¿Dorado o plateado para tu Navidad?", "objective": "Una sola story para apoyar este hito, dentro del total de 15 stories individuales del plan.", "caption": "Un detalle puede cambiar tu rincón ✨\n¿Dorado o plateado?", "outline": ["Una sola composición que compare decoración dorada y plateada, usando fotos ya aprobadas. Encuesta «¿Dorado o plateado?»; complementa P03 del día 19."], "assets": [], "checks": ["Confirmar referencias visibles y disponibilidad."], "script": [], "format": "Imagen vertical · 1 story", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Entregable: exactamente 1 story individual (una imagen, un clip o un recompartido), no una secuencia de varias láminas. Usar banco de los rodajes 5/11 y 19/11 propuesto, o material existente autorizado. No añadir stories extra al paquete. Hora propuesta de Bogotá. Alternancia diaria: una sola story este día; el post corresponde al día anterior o siguiente. Los recompartidos se hacen después de publicar/aprobar el reel original.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='S1117' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "P09", "date": "2026-11-21", "time": "11:30", "end_date": "2026-11-21", "kind": "post", "season": "navidad", "title": "Tu rincón navideño en cuatro pasos", "objective": "Hacer útil el catálogo y aumentar guardados.", "caption": "Un rincón pequeño también puede sentirse navideño 🎄 Elige un árbol, suma una figura, combina los detalles y deja espacio para disfrutarlo.\nDesliza para armar tu idea y guarda esta guía. ¿Qué rincón de tu casa decorarías primero?\nConsulta referencias y disponibilidad con nosotros. 💛", "outline": ["Portada: «Tu rincón navideño en 4 pasos».", "Base: árbol según espacio; no publicar medidas sin ficha.", "Personaje: Papá Noel como acento.", "Detalles: dorado o plateado en composición real.", "Movimiento: tren navideño solo si la referencia y demostración se confirman.", "Cierre: guardar guía + consulta por WhatsApp."], "assets": ["/marketing-assets/08-arboles.jpeg", "/marketing-assets/04-papa-noel.jpeg", "/marketing-assets/05-decoracion-dorada.jpeg", "/marketing-assets/06-decoracion-plateada.jpeg", "/marketing-assets/03-tren-navideno.jpeg"], "checks": ["Confirmar existencias, referencias, sede y precios vigentes el día de publicación."], "script": [], "format": "Carrusel · 1080 × 1350", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Rodaje 2 del jueves 19/11 propuesto: fotos de cada paso del montaje, selección y revisión el 20 para publicar esta guía el 21 a las 11:30. A las 18:30 la complementa R03. Usar referencias disponibles y validadas.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='P09' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "R03", "date": "2026-11-21", "time": "18:30", "end_date": "2026-11-21", "kind": "reel", "season": "navidad", "title": "De rincón vacío a rincón navideño", "objective": "Demostrar transformación y uso real para provocar guardados y consultas.", "caption": "El mismo rincón, otra sensación 🎄✨ Un árbol, una figura y detalles que combinan: así empezamos a preparar Navidad.\n¿Lo harías dorado o plateado? Guarda la idea y consulta las referencias disponibles. 💛🖤\n#DecoraciónNavideña #TiendasImportados #NavidadEnCasa", "outline": ["Duración 20–24 s; cámara fija, antes/después del mismo espacio.", "Las fotos recibidas sirven para escoger referencias; hace falta video real de montaje.", "No atribuir luces, movimiento, medidas o accesorios a productos sin comprobarlos."], "assets": ["/marketing-assets/08-arboles.jpeg", "/marketing-assets/04-papa-noel.jpeg", "/marketing-assets/05-decoracion-dorada.jpeg", "/marketing-assets/06-decoracion-plateada.jpeg", "/marketing-assets/03-tren-navideno.jpeg"], "checks": ["Confirmar existencias, referencias, sede y precios vigentes el día de publicación."], "script": [{"time": "0–2 s", "visual": "Rincón vacío → corte de un segundo al resultado.", "voice": "¿Y si tu rincón de Navidad empezara aquí?", "text": "Mira el antes y el después"}, {"time": "2–7 s", "visual": "Colocar árbol en el encuadre fijo.", "voice": "Empezamos con la base.", "text": "1. Elige tu árbol"}, {"time": "7–12 s", "visual": "Añadir Papá Noel y detalle dorado o plateado.", "voice": "Sumamos un personaje y elegimos un estilo.", "text": "2. Un personaje · 3. Tu estilo"}, {"time": "12–17 s", "visual": "Primeros planos de textura y composición; tren solo probado.", "voice": "Los detalles hacen el resto.", "text": "Dorado o plateado, tú eliges"}, {"time": "17–24 s", "visual": "Plano final igual al inicial + persona observa resultado.", "voice": "Guarda esta idea y cuéntanos cuál harías en tu casa.", "text": "Guárdalo para tu Navidad"}], "format": "Reel · 1080 × 1920", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Rodaje 2 · jueves 19/11 propuesto. Edición y revisión el 20 para publicar el 21 a las 18:30, después de la guía P09 de las 11:30. Primer plano fijo antes/después. Se mantiene dentro de las dos jornadas.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='R03' and plan_id='noviembre-2026';
