and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "S1124", "date": "2026-11-24", "time": "18:30", "end_date": "2026-11-24", "kind": "story", "season": "black-friday", "title": "Agenda Black Friday: 27 al 29", "objective": "Una sola story para apoyar este hito, dentro del total de 15 stories individuales del plan.", "caption": "27, 28 y 29 de noviembre 🖤💛\nBlack Friday · 20 % en toda la tienda\nConsulta condiciones y prepara tu lista.", "outline": ["Una sola pieza con fotos seleccionadas del rodaje 2, fechas 27–29 noviembre, «20 % en toda la tienda» y enlace a condiciones completas. Sin precios de etiqueta no validados."], "assets": [], "checks": ["Confirmar condiciones finales del 20 %, sedes, precio base y vigencia; tener enlace accesible."], "script": [], "format": "Imagen de expectativa · 1 story", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Entregable: exactamente 1 story individual (una imagen, un clip o un recompartido), no una secuencia de varias láminas. Usar banco de los rodajes 5/11 y 19/11 propuesto, o material existente autorizado. No añadir stories extra al paquete. Hora propuesta de Bogotá. Alternancia diaria: una sola story este día; el post corresponde al día anterior o siguiente. Los recompartidos se hacen después de publicar/aprobar el reel original.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='S1124' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "P11", "date": "2026-11-25", "time": "11:30", "end_date": "2026-11-25", "kind": "post", "season": "black-friday", "title": "Black Friday: fechas y condiciones claras", "objective": "Quitar dudas de vigencia y alcance antes de la promoción.", "caption": "Anota las fechas: 27, 28 y 29 de noviembre 🖤💛 En Importados tendremos 20 % de descuento en toda la tienda.\nUna oportunidad para preparar tu Navidad y elegir esos detalles para tu hogar.\nConsulta las condiciones vigentes de la promoción. Escríbenos al WhatsApp 312 706 2214 o visítanos en tienda.\nNiquía: Diagonal 55 Av 38-33, edificio Valkiria, Niquía, Bello. Santa Lucía: Cr. 87 # 47 DD 50, Medellín.", "outline": ["Portada: «Black Friday · 27 al 29 · 20 %».", "Qué incluye: toda la tienda, según alcance y sedes confirmados.", "Cómo comprar: atención en sede y consulta de productos por WhatsApp; no prometer reserva o envío gratis.", "Condiciones completas: vigencia y horario, base de descuento, disponibilidad y acumulabilidad confirmadas.", "Direcciones y WhatsApp."], "assets": [], "checks": ["Validar por escrito alcance del 20 % en toda la tienda, sedes, precio base, vigencia 27–29 noviembre y condiciones. No sumar ni prolongar descuentos de inauguración."], "script": [], "format": "Carrusel · 1080 × 1350", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": " Banco del rodaje 2 del jueves 19/11 propuesto; se completan selección, edición y revisión antes de cada fecha, sin más jornadas. Los datos de precio/stock se revalidan antes de publicar. Alternancia diaria: este es un día de post; las stories van al día siguiente. En los cinco días con reel adicional, post a las 11:30 y reel a las 18:30.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='P11' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "R04", "date": "2026-11-25", "time": "18:30", "end_date": "2026-11-25", "kind": "reel", "season": "black-friday", "title": "La lista navideña se prepara para Black Friday", "objective": "Generar intención de visita para el 27–29 con demostración y oferta clara.", "caption": "Tu lista de Navidad tiene cita en Importados 🖤💛 Este viernes empieza Black Friday: del 27 al 29 de noviembre, 20 % de descuento en toda la tienda.\nÁrboles, decoración y detalles para tu hogar: guarda tus favoritos y consulta las condiciones de la promoción.\nEscríbenos al WhatsApp 312 706 2214 o visítanos en tienda.\n#BlackFriday #TiendasImportados #Navidad", "outline": ["Duración 22–26 s. Producto en primer plano desde el primer segundo.", "Montaje de lista real, sin precios que no se hayan validado.", "Esta pieza abre la campaña; no inventar existencias escasas, reserva ni acumulación con promociones anteriores."], "assets": ["/marketing-assets/08-arboles.jpeg", "/marketing-assets/04-papa-noel.jpeg", "/marketing-assets/07-tren-navideno-set.jpeg", "/marketing-assets/05-decoracion-dorada.jpeg", "/marketing-assets/01-licuadora.jpeg", "/marketing-assets/02-olla-arrocera.jpeg"], "checks": ["Confirmar existencias, referencias, sede y precios vigentes el día de publicación.", "Validar por escrito alcance del 20 % en toda la tienda, sedes, precio base, vigencia 27–29 noviembre y condiciones. No sumar ni prolongar descuentos de inauguración."], "script": [{"time": "0–3 s", "visual": "Persona sostiene lista y árbol/producto ocupa el cuadro.", "voice": "Antes de comprar tu Navidad, mira estas fechas.", "text": "27–29 NOV · Black Friday"}, {"time": "3–10 s", "visual": "Mano marca lista con árbol, Papá Noel y decoración.", "voice": "Árbol, decoración, detalles para regalar… arma tu selección.", "text": "Tu lista navideña"}, {"time": "10–17 s", "visual": "Corte a hogar: olla/licuadora y vuelta a decoración.", "voice": "Del 27 al 29 tenemos 20 % de descuento en toda la tienda.", "text": "20 % · toda la tienda · condiciones vigentes"}, {"time": "17–22 s", "visual": "Fachada y equipo real.", "voice": "Consulta tus favoritos y ven con tu lista.", "text": "Consulta disponibilidad por WhatsApp"}, {"time": "22–26 s", "visual": "Tarjeta clara fecha / sedes.", "voice": "Guarda las fechas. ¡Te esperamos en Importados!", "text": "27, 28 y 29 NOV · guarda este reel"}], "format": "Reel · 1080 × 1920", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Rodaje 2 · jueves 19/11 propuesto. Editar entre 20 y 23, revisar y aprobar el 24; publicar el 25 a las 18:30, después de P11 a las 11:30. Mantener fechas 27–29 y evitar decir «mañana» en esta pieza del 25. La story del 26 sí anuncia el inicio de mañana. No activar pauta automáticamente.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='R04' and plan_id='noviembre-2026';
