 update public.marketing_calendar_items set data='{"id": "P12", "date": "2026-11-27", "time": "08:30", "end_date": "2026-11-27", "kind": "post", "season": "black-friday", "title": "Black Friday empieza hoy", "objective": "Convertir intención acumulada en consultas y visitas.", "caption": "¡Hoy empieza Black Friday en Importados! 🖤💛 Del 27 al 29 de noviembre, 20 % de descuento en toda la tienda.\nEs momento de revisar tu lista y preparar Navidad con árboles, decoración y detalles para regalar.\nConsulta referencias, existencias y condiciones antes de comprar. Escríbenos al WhatsApp 312 706 2214 o visítanos en tienda.\n#BlackFriday #TiendasImportados #NavidadEnCasa", "outline": ["Portada potente: «Empieza hoy · 20 % · 27–29 noviembre».", "Foto real de selección navideña vigente.", "Producto de hogar con precio antes/después solo si ambos fueron validados.", "CTA: «Ven con tu lista» + sedes/condiciones."], "assets": ["/marketing-assets/08-arboles.jpeg", "/marketing-assets/04-papa-noel.jpeg", "/marketing-assets/05-decoracion-dorada.jpeg", "/marketing-assets/01-licuadora.jpeg"], "checks": ["Confirmar existencias, referencias, sede y precios vigentes el día de publicación.", "Validar por escrito alcance del 20 % en toda la tienda, sedes, precio base, vigencia 27–29 noviembre y condiciones. No sumar ni prolongar descuentos de inauguración."], "script": [], "format": "Carrusel · 1080 × 1350", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": " Banco del rodaje 2 del jueves 19/11 propuesto; se completan selección, edición y revisión antes de cada fecha, sin más jornadas. Los datos de precio/stock se revalidan antes de publicar. Alternancia diaria: este es un día de post; las stories van al día siguiente. En los cinco días con reel adicional, post a las 11:30 y reel a las 18:30.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='P12' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "S1127", "date": "2026-11-28", "time": "11:30", "end_date": "2026-11-28", "kind": "story", "season": "black-friday", "title": "Seguimos en Black Friday", "objective": "Una sola story para apoyar este hito, dentro del total de 15 stories individuales del plan.", "caption": "¡Seguimos en Black Friday! 🖤💛\n20 % en toda la tienda hasta el 29 de noviembre\nConsulta disponibilidad y condiciones.", "outline": ["Una sola pieza de selección navideña con texto «Seguimos en Black Friday / 20 % en toda la tienda / Hasta mañana, 29 NOV». Enlace a condiciones/consulta y sin prometer stock."], "assets": [], "checks": ["Condiciones aprobadas, vigencia real y existencias revisadas."], "script": [], "format": "Imagen vertical · 1 story", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Entregable: exactamente 1 story individual (una imagen, un clip o un recompartido), no una secuencia de varias láminas. Usar banco de los rodajes 5/11 y 19/11 propuesto, o material existente autorizado. No añadir stories extra al paquete. Hora propuesta de Bogotá. Alternancia diaria: una sola story este día; el post corresponde al día anterior o siguiente. Los recompartidos se hacen después de publicar/aprobar el reel original.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='S1127' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "P14", "date": "2026-11-29", "time": "09:00", "end_date": "2026-11-29", "kind": "post", "season": "black-friday", "title": "Último día de Black Friday", "objective": "Recordar el cierre real de la promoción sin escasez inventada.", "caption": "¡Hoy, 29 de noviembre, es el último día de nuestro Black Friday! 🖤💛 Aprovecha el 20 % de descuento en toda la tienda, según condiciones de la promoción.\nTrae tu lista de Navidad o consulta por WhatsApp las referencias que te interesan. No dejes para después la visita que ya tenías en mente.\nEscríbenos al WhatsApp 312 706 2214 o visítanos en tienda.", "outline": ["Portada: «Último día · 29 noviembre».", "Dos o tres referencias con disponibilidad comprobada ese mismo día.", "Sedes y horario confirmado para domingo; no asumir horario especial.", "Cierre: «Hoy termina» + condiciones. No usar «últimas unidades» sin conteo real."], "assets": ["/marketing-assets/08-arboles.jpeg", "/marketing-assets/04-papa-noel.jpeg", "/marketing-assets/06-decoracion-plateada.jpeg"], "checks": ["Confirmar existencias, referencias, sede y precios vigentes el día de publicación.", "Validar por escrito alcance del 20 % en toda la tienda, sedes, precio base, vigencia 27–29 noviembre y condiciones. No sumar ni prolongar descuentos de inauguración.", "Confirmar horario de domingo 29/11 y hora exacta de cierre de la promoción."], "script": [], "format": "Carrusel · 1080 × 1350", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": " Banco del rodaje 2 del jueves 19/11 propuesto; se completan selección, edición y revisión antes de cada fecha, sin más jornadas. Los datos de precio/stock se revalidan antes de publicar. Alternancia diaria: este es un día de post; las stories van al día siguiente. En los cinco días con reel adicional, post a las 11:30 y reel a las 18:30.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='P14' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "S1129", "date": "2026-11-30", "time": "18:30", "end_date": "2026-11-30", "kind": "story", "season": "navidad", "title": "Gracias por acompañarnos en Black Friday", "objective": "Una sola story para apoyar este hito, dentro del total de 15 stories individuales del plan.", "caption": "¡Gracias por acompañarnos en Black Friday! 💛🖤\nAhora, a preparar diciembre 🎄\n¿Qué te falta para Navidad?", "outline": ["Una sola imagen de equipo o fachada del banco. Texto «Gracias por acompañarnos / Ahora, a preparar diciembre» y caja «¿Qué te falta para Navidad?». Sin descuento activo ni prórroga."], "assets": [], "checks": ["Retirar rótulos/promociones vencidas; no extender el 20 % después del 29/11."], "script": [], "format": "Imagen vertical · 1 story", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Entregable: exactamente 1 story individual (una imagen, un clip o un recompartido), no una secuencia de varias láminas. Usar banco de los rodajes 5/11 y 19/11 propuesto, o material existente autorizado. No añadir stories extra al paquete. Hora propuesta de Bogotá. Alternancia diaria: una sola story este día; el post corresponde al día anterior o siguiente. Los recompartidos se hacen después de publicar/aprobar el reel original.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='S1129' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "P15", "date": "2026-12-01", "time": "18:30", "end_date": "2026-12-01", "kind": "post", "season": "navidad", "title": "Diciembre empieza en casa", "objective": "Cambiar de descuento a inspiración y compra de temporada.", "caption": "¡Hola, diciembre! 🎄💛 Empieza el mes de los encuentros, los regalos y esos detalles que hacen tu casa más tuya.\nDesliza y arma tu lista: un rincón para decorar, algo para compartir y un detalle para regalar.\nCuéntanos qué estás buscando y revisamos las opciones disponibles. 🖤\n#Navidad #TiendasImportados #Regalos", "outline": ["Portada: «Diciembre empieza en casa».", "Decorar: árboles, Papá Noel y detalles de mesa.", "Compartir: opciones de hogar, sin afirmar funciones técnicas no verificadas.", "Regalar: selección real disponible para distintos gustos; sin precios inventados.", "Lista guardable con casillas: decorar / compartir / regalar."], "assets": ["/marketing-assets/08-arboles.jpeg", "/marketing-assets/04-papa-noel.jpeg", "/marketing-assets/05-decoracion-dorada.jpeg", "/marketing-assets/02-olla-arrocera.jpeg"], "checks": ["Confirmar existencias, referencias, sede y precios vigentes el día de publicación."], "script": [], "format": "Carrusel · 1080 × 1350", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "No arrastrar 20 % después del 29/11. La campaña de diciembre necesita una nueva planeación; esta pieza abre la temporada. Banco del rodaje 2 del jueves 19/11 propuesto; se completan selección, edición y revisión antes de cada fecha, sin más jornadas. Los datos de precio/stock se revalidan antes de publicar. Alternancia diaria: este es un día de post; las stories van al día siguiente. En los cinco días con reel adicional, post a las 11:30 y reel a las 18:30.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='P15' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "S1201", "date": "2026-12-02", "time": "18:30", "end_date": "2026-12-02", "kind": "story", "season": "navidad", "title": "Tu Navidad empieza a tomar forma", "objective": "Una sola story para apoyar este hito, dentro del total de 15 stories individuales del plan.", "caption": "Diciembre ya está aquí 🎄💛\n¿Qué te falta para decorar tu casa?", "outline": ["Una sola imagen navideña del rodaje 2. Texto «¿Qué te falta para decorar?» y caja de preguntas; complementa P15 del 1/12."], "assets": [], "checks": ["Validar referencias disponibles y evitar descuentos vencidos."], "script": [], "format": "Imagen vertical · 1 story", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Entregable: exactamente 1 story individual (una imagen, un clip o un recompartido), no una secuencia de varias láminas. Usar banco de los rodajes 5/11 y 19/11 propuesto, o material existente autorizado. No añadir stories extra al paquete. Hora propuesta de Bogotá. Alternancia diaria: una sola story este día; el post corresponde al día anterior o siguiente. Los recompartidos se hacen después de publicar/aprobar el reel original.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='S1201' and plan_id='noviembre-2026';
 update public.marketing_calendar_items set data='{"id": "P13", "date": "2026-12-03", "time": "11:30", "end_date": "2026-12-03", "kind": "post", "season": "navidad", "title": "Arma tu selección navideña", "objective": "Mantener inspiración y consultas navideñas después de Black Friday, con productos reales.", "caption": "¿Ya elegiste cómo se verá tu Navidad? 🎄💛 Arma tu selección con árboles, figuras y detalles que combinen contigo.\nDesliza para inspirarte, guarda tus favoritos y pregúntanos por las referencias disponibles.\n¿Dorado o plateado para tu casa? 🖤\n#NavidadEnCasa #TiendasImportados #DecoraciónNavideña", "outline": ["Portada: «Arma tu selección navideña».", "Selección dorada: productos reales identificados, sin asumir precio de conjunto.", "Selección plateada: composición equivalente para comparar estilos.", "Rincón con Papá Noel, árbol y tren si las referencias están disponibles.", "Cierre: «Guarda tu estilo y consulta tus favoritos» + WhatsApp. Sin descuentos vencidos."], "assets": ["/marketing-assets/05-decoracion-dorada.jpeg", "/marketing-assets/06-decoracion-plateada.jpeg", "/marketing-assets/04-papa-noel.jpeg", "/marketing-assets/08-arboles.jpeg", "/marketing-assets/07-tren-navideno-set.jpeg"], "checks": ["Confirmar existencias, referencias, sede y precios vigentes el día de publicación."], "script": [], "format": "Carrusel · 1080 × 1350", "status": "planned", "responsible": "Polaris · contenido / Importados · validación", "production_notes": "Banco del rodaje 2 del 19/11 propuesto. Esta publicación se traslada al 3/12 y pasa a Navidad sin promoción de Black Friday. Retirar cualquier rótulo del 20 % o de fechas vencidas.", "revision": 1}'::jsonb,revision=revision+1,updated_at=now() where id='P13' and plan_id='noviembre-2026';
 update public.marketing_calendar_plans set meta='{"title": "Calendario comercial · noviembre 2026", "edition": "2026-11-03", "timezone": "America/Bogota", "start": "2026-11-01", "end": "2026-12-06", "scope": "Presencia diaria del 4/11 al 3/12: 15 días de post alternados con 15 días de story individual. Los 5 reels refuerzan cinco días de post, separados en horario (post 11:30 / reel 18:30). Total: 5 reels + 15 posts + 15 stories. Dos rodajes: 5/11 confirmado y 19/11 propuesto. El calendario no publica ni activa pauta.", "strategy": [{"title": "Cinco reels, funciones distintas", "body": "R01: recorrido POV local. R02: invitación orgánica breve de tres motivos. R03: antes/después navideño. R04: lista navideña/Black Friday. R05: anuncio adicional de inauguración con todas las dinámicas, pensado para Meta Ads y publicado el 9/11 antes del evento. Son hipótesis creativas para la tienda, sin promesa de viralidad."}, {"title": "Una campaña que acumula intención", "body": "Del 4/11 al 3/12 hay una publicación base diaria: story y post se alternan sin días vacíos. Las stories mantienen conversación y recuerdan la pieza previa; los posts desarrollan el mensaje. Los cinco reels se suman en cinco días de post, con horarios distintos, sin consumir ni aumentar las 15 stories. Inauguración: story el 14 y post el 15; Black Friday: post el 27, story el 28 y post el 29."}, {"title": "Grabación que se puede ejecutar", "body": "Solo dos rodajes profesionales. Jueves 5/11 confirmado: R01, R02, R05 y banco fotográfico/recursos de inauguración y primera selección navideña. Jueves 19/11 propuesto: R03, R04 y banco de Navidad/Black Friday para el cierre. Horario sugerido 09:00–14:00 ambos días. El resto es edición, diseño y programación; no hay rodajes el 4, 9, 16 o 23. Para memorias de eventos, usar material existente/espontáneo compartido por tienda o agradecimientos gráficos; no fingir cobertura. Video propio vertical, voz, subtítulos y música apta para uso comercial. Las 15 stories se producen con ese mismo banco: una sola pieza por entrada del calendario. El banco alimenta las 15 fechas de story del calendario alternado; no se añaden piezas al paquete."}, {"title": "Horario de partida, no «mejor hora» probada", "body": "America/Bogota. Alternar story/post diariamente del 4 de noviembre al 3 de diciembre: 15 de cada formato. En los cinco días con reel, post a las 11:30 y reel a las 18:30; son dos publicaciones de feed ese día. Reels: 5, 9, 11, 21 y 25 de noviembre. En días de story no se añade post ni reel. Los anuncios de inicio/cierre conservan horario temprano según el calendario. Horarios propuestos, ajustables con Insights; no se afirma una mejor hora probada para la cuenta."}, {"title": "Medición útil para retail", "body": "A las 24 h y 7 días: alcance, tiempo medio de reproducción y retención si están disponibles, compartidos/alcance, guardados/alcance, visitas al perfil y seguidores netos. Registrar consultas cualificadas por pieza (producto + sede + intención), visitas autodeclaradas y ventas verificadas por separado. No confundir reproducción, clic o consulta con venta."}, {"title": "Pauta después de validar la pieza", "body": "R05 es la pieza adicional dedicada a convocatoria de inauguración: publicar el 9/11, con rodaje el 5, edición 6, revisión 7 y cierre de condiciones/aprobación 8. Propuesta de pauta 9–13/11, sin gasto ni activación desde el módulo. R02 queda orgánico para no duplicar inversión. R04 puede apoyar Black Friday si se autoriza otra campaña. Definir presupuesto, objetivo, destino y área de captación real de Niquía; comprobar bases y elegibilidad del anuncio antes de pautar premios. Medir consultas/visitas y ventas verificadas por separado, sin prometer resultados."}, {"title": "Productos reales, no catálogo cerrado", "body": "Las ocho fotos aportadas son referencias de licuadora, arrocera, trenes, Papá Noel, detalles dorados/plateados y árboles. Las etiquetas fotografiadas no son autorización para anunciar precios ni aplicarles otro descuento. Solicitar un inventario visual adicional de Navidad; mostrar luces, bolas, guirnaldas o empaques solo si se confirma que se venden."}, {"title": "Revisión de Instagram: alcance y límite", "body": "Se intentó revisar el perfil público y su embed el 3/11/2026: Instagram bloqueó la lectura automatizada y la búsqueda no recuperó publicaciones verificables. No se atribuyen métricas, frecuencia ni piezas recientes a la cuenta. El material previamente compartido muestra fachada, presentadora y estética amarilla/negra; se mantiene esa continuidad. Antes de producir, el equipo debe contrastar los 19 temas con el feed real y evitar duplicados."}, {"title": "Promociones con información clara", "body": "Inauguración: 20 % en casi toda la tienda, sin transformarlo en «toda». Black Friday: 20 % en toda la tienda 27–29, pendiente de condiciones finales. Rifa: compra y seguir Instagram confirmados; faltan bases. Concurso: dos componentes de $500.000, sin sumar como efectivo. Artista: imitadora de Arelys Henao, sin aparentar contratación de la cantante original. Horarios de shows sin definir."}], "sources": [{"title": "Meta · Best Practices de Instagram", "url": "https://about.fb.com/news/2024/10/best-practices-education-hub-creators-instagram/", "finding": "Meta organiza recomendaciones de creación, interacción y alcance y ofrece consejos personalizados en el panel profesional. Sustenta revisar Insights propios, sin afirmar una hora universal."}, {"title": "Meta · Trial Reels", "url": "https://about.fb.com/news/2024/12/trial-reels-try-content-non-followers-first-see-what-perfoms-best/", "finding": "Meta describe pruebas con no seguidores para explorar formatos. Si la función aparece en la cuenta, usarla en R01 o R03; mantener R02 y R04 en el calendario normal por su vigencia. El plan ahora incluye el quinto reel de pauta autorizado por Samuel; las tomas alternativas no añaden más reels."}, {"title": "Meta · Creatividad y pruebas", "url": "https://about.fb.com/news/2025/06/inspiring-creativity-that-brings-people-together/", "finding": "Apoya experimentar con contenido y observar la respuesta. Los formatos y guiones propuestos aquí son una inferencia creativa para Importados, no un estudio de ventas de esta cuenta."}, {"title": "Instagram de Importados · revisión manual pendiente", "url": "https://www.instagram.com/tiendasimportados/", "finding": "Fuente propia a contrastar por el equipo; no se pudo auditar el feed actual desde esta sesión."}], "production_revision": "two-shoots-v2", "stories_revision": "15-individual-stories-v3", "cadence_revision": "alternating-daily-v4", "publication_start": "2026-11-04", "publication_end": "2026-12-03"}'::jsonb where id='noviembre-2026';
end $calendar$;
commit;
